    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'ICON-SET', qty: 1 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.deepEqual(result.value.lines[1], {
    sku: 'ICON-SET',
    name: 'Icon set (24 icons)',
    qty: 1,
    unitPrice: 980,
    vatRate: 21,
  });
});

