});

test('issueInvoice assigns number and changes status to issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = issueInvoice(invoice, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0001');
  assert.equal(result.value.status, 'issued');
});

test('issueInvoice increments counter', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const result = issueInvoice(invoice, existing);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0003');
