    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = issueInvoice(invoice, []);

  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.lines.length, 1);
  assert.deepEqual(result.value.lines[0], invoice.lines[0]);
});

test('issueInvoice returns NOT_DRAFT for issued invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DES-HOUR', qty: 2, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = issueInvoice(invoice, []);

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('issueInvoice does not mutate original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const originalStatus = invoice.status;
  const originalHasNumber = 'number' in invoice;

  issueInvoice(invoice, []);

  assert.equal(invoice.status, originalStatus);
  assert.equal('number' in invoice, originalHasNumber);
});

